{
    "manifest_version": 1,
    "provider": {
        "name": "process_pisco_profiles",
        "description": "Post-processing of PIScO profiles: EcoTaxa export and upload.",
        "version": "1.0"
    },
    "tools": [
        {
            "name": "pisco_ecotaxa_export",
            "description": "Export an EcoTaxa import archive from the C++ segmenter's result.h5. Writes one PNG per object plus an ecotaxa_<profile>.tsv with acquisition metadata and zooprocess morphometrics, zipped ready for import. If pisco_deconvolve ran before extraction the crops are already deconvolved.",
            "tags": [
                "pisco",
                "ecotaxa",
                "export"
            ],
            "program_path": "run.sh",
            "program_type": "binary",
            "working_directory": ".",
            "default_priority": 3,
            "default_weight": 2,
            "failed_ok": false,
            "requires": [
                "pisco-tools"
            ],
            "settings_format": "ini",
            "settings_schema": {
                "type": "object",
                "required": [
                    "sourcePath",
                    "targetPath"
                ],
                "properties": {
                    "sourcePath": {
                        "type": "string",
                        "description": "Segmenter results directory holding result.h5, or the result.h5 itself. This is the OBJECT_EXTRACTION output, not the correction checkpoints."
                    },
                    "targetPath": {
                        "type": "string",
                        "description": "Directory for the crops, the TSV and the zip. Leave empty to let the Hub choose."
                    },
                    "profileName": {
                        "type": "string",
                        "default": "",
                        "description": "Profile name, used as EcoTaxa sample_id and in the archive filename. Empty uses the results directory name."
                    },
                    "maxZipSizeMb": {
                        "type": "integer",
                        "minimum": 1,
                        "default": 500,
                        "description": "Split the export into multiple archives above this size. Each part carries its own TSV."
                    },
                    "minSize": {
                        "type": "integer",
                        "minimum": 0,
                        "default": 0,
                        "description": "Drop objects whose bounding box width and height are both at or below this many pixels. 0 keeps everything the segmenter found."
                    },
                    "gaugePressure": {
                        "type": "boolean",
                        "default": false,
                        "description": "Treat the pressure in the frame name as gauge pressure. By default it is absolute and 10.1325 dbar is subtracted to give depth."
                    },
                    "ctdCast": {"type": "integer", "minimum": 1, "description": "Running number of the CTD cast PIScO rode on; written to every object as sample_ctd_cast. Optional."},
                    "linkBase": {
                        "type": "string",
                        "default": "",
                        "description": "Hub base URL, e.g. http://10.11.11.110:5000. When set, every object gets an EcoTaxa object_link that opens the HDF profile viewer on that object in its frame. Leave empty for no links."
                    },
                    "scaleBar": {
                        "type": "boolean",
                        "default": true,
                        "description": "Draw a scale bar under each crop. Uses the repo's reversible strip: the crop's own pixels are untouched and its original size is recorded in the PNG, so strip_scale_bar() restores it exactly before the crop reaches a classifier. The bar is 1 mm where it fits and 500 um otherwise."
                    },
                    "pixelSizeUm": {
                        "type": "number",
                        "minimum": 0.001,
                        "default": 22.5,
                        "description": "Micrometres per pixel, for the scale bar and object_esd alike. 22.5 is PISCO2; set the camera's own value for any other."
                    },
                    "predictionsPath": {
                        "type": "string",
                        "default": "",
                        "description": "pisco_vit_classify output directory (or its predictions.csv). Its labels are written into the TSV as annotations, so predictions arrive with the import and no second trip to EcoTaxa is needed. In a dual-ViT chain point this at the LAST stage: with carryForward on it already covers every object, the taxon labels where it classified and the binary verdict elsewhere. Comma-separating several stages also works for manual runs, applied in order. Chain with {\"$from\": {\"task\": N, \"output\": \"predictions\"}}."
                    },
                    "taxonomyMapPath": {
                        "type": "string",
                        "default": "",
                        "description": "ecotaxa_taxonomy_map.json. Required when predictionsPath is set: the TSV carries numeric EcoTaxa taxon ids (object_annotation_category_id), not label names, because names are ambiguous. Export fails if the map still has unresolved labels."
                    },
                    "isolateCrops": {
                        "type": "boolean",
                        "default": true,
                        "description": "Write each crop as the object alone in a tight box, everything outside its mask white - the crop the python route saved and the classifier was trained on. Off writes the segmenter's stored box as-is, with its padding and any neighbours."
                    }
                }
            },
            "inputs": [
                {
                    "name": "results",
                    "kind": "directory",
                    "settings_key": "sourcePath",
                    "description": "Segmenter OBJECT_EXTRACTION output containing result.h5"
                }
            ],
            "outputs": [
                {
                    "name": "export",
                    "kind": "directory",
                    "settings_key": "targetPath",
                    "description": "EcoTaxa import archive(s), crops and TSV"
                }
            ]
        },
        {
            "name": "pisco_vit_classify",
            "description": "Run a ViT over the crops in the segmenter's result.h5. One stage of the dual-ViT setup: chain two tasks, a binary living/not-living pass over everything (with emitEmbeddings on), then a taxon pass restricted to the living ones. Reads crops straight from the HDF5, so no scale bar to strip and isolation stays a choice made at inference time.",
            "tags": [
                "pisco",
                "ml",
                "vit",
                "classification"
            ],
            "program_path": "run_vit.sh",
            "program_type": "binary",
            "working_directory": ".",
            "default_priority": 3,
            "default_weight": 6,
            "failed_ok": false,
            "requires": [
                "pisco-tools",
                "gpu"
            ],
            "settings_format": "ini",
            "settings_schema": {
                "type": "object",
                "required": [
                    "sourcePath",
                    "targetPath",
                    "modelPath"
                ],
                "properties": {
                    "sourcePath": {
                        "type": "string",
                        "description": "Segmenter results directory holding result.h5, or the file itself."
                    },
                    "targetPath": {
                        "type": "string",
                        "description": "Directory for predictions.csv and, if requested, embeddings.npz. Leave empty to let the Hub choose."
                    },
                    "modelPath": {
                        "type": "string",
                        "description": "Model directory on this machine, or a Hugging Face repo id (e.g. Veit/diplo-vit-plankton). This is the stage's model: the binary one for the first pass, the taxon one for the second. A pisco_vit_train output directory also works - its best_model/ is found automatically - so a retrained model can be chained straight in with {\"$from\": {\"task\": N, \"output\": \"model\"}}."
                    },
                    "isolateCrops": {
                        "type": "boolean",
                        "default": true,
                        "description": "Cut each crop to its mask's box and white out everything outside the mask - the crop the python route saved and the ViTs were trained on. Off feeds the segmenter's stored box as-is, with its padding and any neighbours in it."
                    },
                    "emitEmbeddings": {
                        "type": "boolean",
                        "default": false,
                        "description": "Also write the encoder CLS vectors, for EcoTaxa's similarity search. Set this on the stage that sees EVERY object (the binary one): EcoTaxa disables similarity search for a whole project if any object lacks a feature vector."
                    },
                    "batchSize": {
                        "type": "integer",
                        "minimum": 1,
                        "default": 64,
                        "description": "Crops per GPU batch. 64 fits an 8 GB card in fp32; 256 is fine on a 3080 in fp16."
                    },
                    "topK": {
                        "type": "integer",
                        "minimum": 1,
                        "default": 5,
                        "description": "How many ranked labels to record per object."
                    },
                    "restrictToPath": {
                        "type": "string",
                        "default": "",
                        "description": "Earlier stage's output directory (or its predictions.csv). Only objects whose top1 label is in restrictLabels are classified. This is how the taxon stage is limited to living crops; chain it with {\"$from\": {\"task\": 0, \"output\": \"predictions\"}}."
                    },
                    "restrictLabels": {
                        "type": "string",
                        "default": "living",
                        "description": "Comma-separated top1 labels to keep, when restrictToPath is set."
                    },
                    "carryForward": {
                        "type": "boolean",
                        "default": true,
                        "description": "With restrictToPath, keep the earlier stage's rows for objects this stage skips, so predictions.csv covers every object. Leave on: it lets a downstream task reference this stage alone, which matters because the Hub resolves $from inside dicts but not inside lists, so two references cannot be combined in one setting."
                    },
                    "workers": {
                        "type": "integer",
                        "minimum": 0,
                        "description": "Processes preprocessing crops while the GPU runs the previous batch. Leave unset for up to 8 (one less than the cores); 0 does it inline."
                    },
                    "precision": {
                        "type": "string",
                        "enum": [
                            "auto",
                            "fp16",
                            "fp32"
                        ],
                        "default": "auto",
                        "description": "auto runs fp16 on GPUs with tensor cores (RTX 3060/3080) and fp32 on Pascal (Tesla P4), where fp16 is slower."
                    }
                }
            },
            "inputs": [
                {
                    "name": "results",
                    "kind": "directory",
                    "settings_key": "sourcePath",
                    "description": "Segmenter OBJECT_EXTRACTION output containing result.h5"
                }
            ],
            "outputs": [
                {
                    "name": "predictions",
                    "kind": "directory",
                    "settings_key": "targetPath",
                    "description": "predictions.csv and optionally embeddings.npz"
                }
            ]
        },
