def resolve_params(obj, params):
    """Copy of the settings with $param and $format references filled in
    from the workflow's params. $from references are left alone.

    Raises ValueError naming the setting and the parameter it misses, so
    a workflow with a typo is rejected when it is created.
    """
    params = _Params(params or {})

    def walk(value, path):
        kind = ref_kind(value)
        if kind == PARAM_KEY:
            name = value[PARAM_KEY]
            if not isinstance(name, str):
                raise ValueError(f"'{path}': $param must name a parameter")
            if name not in params:
                raise ValueError(
                    f"'{path}': no workflow parameter '{name}'")
            return params[name]
        if kind == FORMAT_KEY:
            template = value[FORMAT_KEY]
            if not isinstance(template, str):
                raise ValueError(f"'{path}': $format must be a string")
            try:
                return template.format_map(params)
            except KeyError as e:
                raise ValueError(
                    f"'{path}': $format uses unknown parameter {e}")
            except (ValueError, IndexError) as e:
                raise ValueError(f"'{path}': bad $format string: {e}")
        if isinstance(value, dict):
            return {key: walk(inner, f"{path}.{key}" if path else key)
                    for key, inner in value.items()}
        if isinstance(value, list):
            return [walk(inner, path) for inner in value]
        return value

    return walk(obj, "")


def drop_unset_params(obj, params_schema, params):
    """Copy of the settings without the keys whose value is a bare
    {"$param": name} for a parameter the template declares but the run
    left out. An optional parameter then means what it says: the tool's
    own default applies instead of the run being rejected. A parameter
    the template does not declare is still an error in resolve_params.
    """
    if isinstance(params_schema, str):
        params_schema = json.loads(params_schema) if params_schema else {}
    declared = set((params_schema or {}).get("properties", {}))
    unset = declared - set(params or {})
    if not unset:
        return obj

